1	package warranty
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// Product 是登记的产品保修信息。
10	type Product struct {
11		// ID 是唯一产品编号。
12		ID string
13		// PurchaseTime 是购买时刻。
14		PurchaseTime time.Time
15		// WarrantyDays 是保修天数，必须为正整数；保修期自购买时刻起，每天按二十四小时计算。
16		WarrantyDays int
17		// ExcludedCodes 是除外故障代码集合；命中代码的请求一律拒绝。
18		ExcludedCodes map[string]struct{}
19	}
20	
21	// Part 是登记的备件及其库存。
22	type Part struct {
23		// ID 是唯一备件编号。
24		ID string
25		// Stock 是当前剩余实物库存，被成功使用的承诺分批扣减。
26		Stock int
27	}
28	
29	// Request 是提交的保修请求，指定产品和故障代码。
30	type Request struct {
31		// ID 是唯一请求编号。
32		ID string
33		// ProductID 是关联的产品编号。
34		ProductID string
35		// FaultCode 是故障代码，不能为空。
36		FaultCode string
37	}
38	
39	// CommitmentStatus 是承诺的当前状态。
40	type CommitmentStatus string
41	
42	const (
43		// CommitmentActive 表示承诺有效：未取消且未到期。
44		CommitmentActive CommitmentStatus = "active"
45		// CommitmentCanceled 表示承诺已被取消。
46		CommitmentCanceled CommitmentStatus = "canceled"
47		// CommitmentExpired 表示承诺已到期，余量自动释放。
48		CommitmentExpired CommitmentStatus = "expired"
49	)
50	
51	// Commitment 是一笔备件承诺。
52	type Commitment struct {
53		// ID 是全局唯一的提交编号。
54		ID string
55		// RequestID 是关联的请求编号。
56		RequestID string
57		// PartID 是预留的备件编号。
58		PartID string
59		// Quantity 是原定承诺数量（正整数）。
60		Quantity int
61		// Used 是已成功使用的累计数量。
62		Used int
63		// Expiry 是到期时刻；当前时刻等于或晚于它时承诺自动失效。
64		Expiry time.Time
65		// Canceled 表示是否已被取消。
66		Canceled bool
67	}
68	
69	// Unused 返回未用数量。
70	func (c *Commitment) Unused() int { return c.Quantity - c.Used }
71	
72	// Status 返回承诺在指定当前时刻的状态。
73	func (c *Commitment) Status(now time.Time) CommitmentStatus {
74		switch {
75		case c.Canceled:
76			return CommitmentCanceled
77		case !now.Before(c.Expiry):
78			return CommitmentExpired
79		default:
80			return CommitmentActive
81		}
82	}
83	
84	// Usage 是一次成功的承诺使用记录。
85	type Usage struct {
86		// ID 是全局唯一的使用编号。
87		ID string
88		// CommitmentID 是被扣减的承诺编号。
89		CommitmentID string
90		// Quantity 是本次使用的正整数数量。
91		Quantity int
92	}
93	
94	// Store 保存全部登记信息与承诺。所有方法均为并发安全。
95	type Store struct {
96		mu          sync.Mutex
97		products    map[string]*Product
98		parts       map[string]*Part
99		requests    map[string]*Request
100		commitments map[string]*Commitment
101		usages      map[string]*Usage
102		// history 保存按请求分组的预留处理历史，仅存在于当前仓库实例中。
103		history map[string][]HistoryRecord
104	}
105	
106	// NewStore 创建一个空的保修备件仓库。
107	func NewStore() *Store {
108		return &Store{
109			products:    make(map[string]*Product),
110			parts:       make(map[string]*Part),
111			requests:    make(map[string]*Request),
112			commitments: make(map[string]*Commitment),
113			usages:      make(map[string]*Usage),
114			history:     make(map[string][]HistoryRecord),
115		}
116	}
117	
118	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
119	// 编号重复时返回 ErrDuplicateID 且保留原记录。
120	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
121		if id == "" {
122			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
123		}
124		if warrantyDays <= 0 {
125			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
126		}
127		s.mu.Lock()
128		defer s.mu.Unlock()
129		if _, ok := s.products[id]; ok {
130			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
131		}
132		codes := make(map[string]struct{}, len(excludedCodes))
133		for _, c := range excludedCodes {
134			if c == "" {
135				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
136			}
137			codes[c] = struct{}{}
138		}
139		s.products[id] = &Product{
140			ID:            id,
141			PurchaseTime:  purchaseTime,
142			WarrantyDays:  warrantyDays,
143			ExcludedCodes: codes,
144		}
145		return nil
146	}
147	
148	// RegisterPart 登记备件及其非负整数初始库存。
149	// 编号重复时返回 ErrDuplicateID 且保留原记录。
150	func (s *Store) RegisterPart(id string, initialStock int) error {
151		if id == "" {
152			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
153		}
154		if initialStock < 0 {
155			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
156		}
157		s.mu.Lock()
158		defer s.mu.Unlock()
159		if _, ok := s.parts[id]; ok {
160			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
161		}
162		s.parts[id] = &Part{ID: id, Stock: initialStock}
163		return nil
164	}
165	
166	// SubmitRequest 提交保修请求，指定产品和故障代码。
167	// 编号重复时返回 ErrDuplicateID 且保留原记录。
168	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
169		if id == "" {
170			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
171		}
172		if faultCode == "" {
173			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
174		}
175		s.mu.Lock()
176		defer s.mu.Unlock()
177		if _, ok := s.requests[id]; ok {
178			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
179		}
180		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
181		return nil
182	}
183	
184	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
185	func (s *Store) Product(id string) (Product, error) {
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		p, ok := s.products[id]
189		if !ok {
190			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
191		}
192		cp := *p
193		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
194		for k := range p.ExcludedCodes {
195			cp.ExcludedCodes[k] = struct{}{}
196		}
197		return cp, nil
198	}
199	
200	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
201	func (s *Store) Part(id string) (Part, error) {
202		s.mu.Lock()
203		defer s.mu.Unlock()
204		p, ok := s.parts[id]
205		if !ok {
206			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
207		}
208		return *p, nil
209	}
210	
211	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
212	func (s *Store) Request(id string) (Request, error) {
213		s.mu.Lock()
214		defer s.mu.Unlock()
215		r, ok := s.requests[id]
216		if !ok {
217			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
218		}
219		return *r, nil
220	}
221	
222	// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
223	func (s *Store) Commitment(id string) (Commitment, error) {
