1	package warranty
2	
3	import (
4		"fmt"
5		"time"
6	)
7	
8	// activeOccupiedLocked 返回某备件在指定当前时刻的有效承诺未用总量。
9	// 已取消或已到期的承诺不计入占用。
10	func (s *Store) activeOccupiedLocked(partID string, now time.Time) int {
11		total := 0
12		for _, c := range s.commitments {
13			if c.PartID != partID {
14				continue
15			}
16			if c.Canceled || !now.Before(c.Expiry) {
17				continue
18			}
19			total += c.Quantity - c.Used
20		}
21		return total
22	}
23	
24	// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于当前时刻。
25	// 每次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
26	// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
27	//
28	// 提交编号全局唯一：相同编号且相同内容的重试返回同一承诺，不追加历史；
29	// 换请求、备件、数量或到期时刻则返回 ErrConflict，并在本次提交指定的已知
30	// 请求下记录失败。每次首次预留成功及每次失败提交都会在对应请求下留下记录。
31	func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
32		s.mu.Lock()
33		defer s.mu.Unlock()
34	
35		if commitID == "" || requestID == "" || partID == "" {
36			s.recordInvalidParamLocked(requestID, commitID, partID, quantity, expiry, now)
37			return Commitment{}, fmt.Errorf("%w: commit/request/part id must not be empty", ErrInvalidParam)
38		}
39		if quantity <= 0 {
40			s.recordInvalidParamLocked(requestID, commitID, partID, quantity, expiry, now)
41			return Commitment{}, fmt.Errorf("%w: reserve quantity must be a positive integer", ErrInvalidParam)
42		}
43		if !expiry.After(now) {
44			s.recordInvalidParamLocked(requestID, commitID, partID, quantity, expiry, now)
45			return Commitment{}, fmt.Errorf("%w: expiry must be after current time", ErrInvalidParam)
46		}
47	
48		// 幂等重试：同编号同内容返回首次结果，不追加历史，不重复占用。
49		if existing, ok := s.commitments[commitID]; ok {
50			if existing.RequestID != requestID || existing.PartID != partID ||
51				existing.Quantity != quantity || !existing.Expiry.Equal(expiry) {
52				// 冲突：在本次提交指定的已知请求下记录失败，不挂到原承诺所属请求。
53				if _, known := s.requests[requestID]; known {
54					s.appendHistoryLocked(requestID, HistoryRecord{
55						CommitID: commitID,
56						PartID:   partID,
57						Quantity: quantity,
58						Expiry:   expiry,
59						Now:      now,
60						Error:    HistoryErrorConflict,
61					})
62				}
63				return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
64			}
65			return *existing, nil
66		}
67	
68		req, ok := s.requests[requestID]
69		if !ok {
70			return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
71		}
72		part, ok := s.parts[partID]
73		if !ok {
74			s.appendHistoryLocked(requestID, HistoryRecord{
75				CommitID: commitID,
76				PartID:   partID,
77				Quantity: quantity,
78				Expiry:   expiry,
79				Now:      now,
80				Error:    HistoryErrorPartNotFound,
81			})
82			return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
83		}
84		elig, err := s.evaluateLocked(req, now)
85		if err != nil {
86			// 产品未登记：资格依据明确为空，不用合格替代缺失。
87			s.appendHistoryLocked(requestID, HistoryRecord{
88				CommitID: commitID,
89				PartID:   partID,
90				Quantity: quantity,
91				Expiry:   expiry,
92				Now:      now,
93				Error:    HistoryErrorProductNotFound,
94			})
95			return Commitment{}, err
96		}
97	
98		// 库存依据：本次提交处理前的实物剩余、有效占用与可承诺数量。
99		stockBasis := &StockBasis{
100			PhysicalRemaining: part.Stock,
101			ActiveOccupied:    s.activeOccupiedLocked(partID, now),
102		}
103		stockBasis.Committable = stockBasis.PhysicalRemaining - stockBasis.ActiveOccupied
104	
105		if !elig.Eligible {
106			s.appendHistoryLocked(requestID, HistoryRecord{
107				CommitID:    commitID,
108				PartID:      partID,
109				Quantity:    quantity,
110				Expiry:      expiry,
111				Now:         now,
112				Error:       HistoryErrorIneligible,
113				Eligibility: cloneEligibility(elig),
114				StockBasis:  stockBasis,
115			})
116			return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
117		}
118	
119		if quantity > stockBasis.Committable {
120			s.appendHistoryLocked(requestID, HistoryRecord{
121				CommitID:    commitID,
122				PartID:      partID,
123				Quantity:    quantity,
124				Expiry:      expiry,
125				Now:         now,
126				Error:       HistoryErrorInsufficientStock,
127				Eligibility: cloneEligibility(elig),
128				StockBasis:  stockBasis,
129			})
130			return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, stockBasis.Committable)
131		}
132	
133		c := &Commitment{
134			ID:        commitID,
135			RequestID: requestID,
136			PartID:    partID,
137			Quantity:  quantity,
138			Expiry:    expiry,
139		}
140		// 成功记录与承诺在同一把锁内同时落库，查询不会看到只占用库存却没有
141		// 成功记录的中间状态。
142		s.commitments[commitID] = c
143		s.appendHistoryLocked(requestID, HistoryRecord{
144			CommitID:    commitID,
145			PartID:      partID,
146			Quantity:    quantity,
147			Expiry:      expiry,
148			Now:         now,
149			Success:     true,
150			Eligibility: cloneEligibility(elig),
151			StockBasis:  stockBasis,
152		})
153		return *c, nil
154	}
155	
156	// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
157	// 数量超过未用数量时整次失败，不改变任何记录。
158	//
159	// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减；
160	// 改数量或改承诺返回 ErrConflict。已经成功的使用在承诺取消或到期后重试，
161	// 仍返回原结果。已全部使用的承诺不再接受新使用。
162	func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
163		if usageID == "" || commitID == "" {
164			return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
165		}
166		if quantity <= 0 {
167			return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
168		}
169		s.mu.Lock()
170		defer s.mu.Unlock()
171	
172		if existing, ok := s.usages[usageID]; ok {
173			if existing.CommitmentID != commitID || existing.Quantity != quantity {
174				return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
175			}
176			return *existing, nil
177		}
178	
179		c, ok := s.commitments[commitID]
180		if !ok {
181			return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
182		}
183		if c.Canceled {
184			return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
185		}
186		if !now.Before(c.Expiry) {
187			return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
188		}
189		if quantity > c.Quantity-c.Used {
190			return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
191		}
192	
193		c.Used += quantity
194		s.parts[c.PartID].Stock -= quantity
195		u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
196		s.usages[usageID] = u
197		return *u, nil
198	}
199	
200	// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
201	// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
202	// 取消后的承诺不能继续使用。
203	func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
204		if commitID == "" {
205			return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
206		}
207		s.mu.Lock()
208		defer s.mu.Unlock()
209	
210		c, ok := s.commitments[commitID]
211		if !ok {
212			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
213		}
214		if !c.Canceled {
215			c.Canceled = true
216		}
217		return *c, nil
218	}
219

