1	package warranty
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// historyStore 构造一个带产品/备件/请求的仓库。
12	func historyStore(t *testing.T) *Store {
13		t.Helper()
14		s := NewStore()
15		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
16			t.Fatalf("register product: %v", err)
17		}
18		if err := s.RegisterPart("part1", 10); err != nil {
19			t.Fatalf("register part: %v", err)
20		}
21		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
22			t.Fatalf("submit request: %v", err)
23		}
24		return s
25	}
26	
27	func TestHistoryEmptyAndValidation(t *testing.T) {
28		s := historyStore(t)
29	
30		// 已知请求没有记录时返回空列表（非 nil）。
31		h, err := s.RequestHistory("r1")
32		if err != nil {
33			t.Fatalf("history: %v", err)
34		}
35		if h == nil || len(h) != 0 {
36			t.Fatalf("expected empty non-nil history, got %v", h)
37		}
38	
39		// 空请求编号 → ErrInvalidParam。
40		if _, err := s.RequestHistory(""); !errors.Is(err, ErrInvalidParam) {
41			t.Fatalf("empty request id: got %v", err)
42		}
43		// 未知请求 → ErrNotFound。
44		if _, err := s.RequestHistory("rMissing"); !errors.Is(err, ErrNotFound) {
45			t.Fatalf("unknown request: got %v", err)
46		}
47	}
48	
49	func TestHistorySuccessRecord(t *testing.T) {
50		s := historyStore(t)
51		c, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
52		if err != nil {
53			t.Fatalf("reserve: %v", err)
54		}
55		h, err := s.RequestHistory("r1")
56		if err != nil {
57			t.Fatalf("history: %v", err)
58		}
59		if len(h) != 1 {
60			t.Fatalf("history len = %d, want 1", len(h))
61		}
62		rec := h[0]
63		if rec.Seq != 1 || !rec.Success || rec.Error != "" {
64			t.Fatalf("bad success marker: seq=%d success=%v error=%q", rec.Seq, rec.Success, rec.Error)
65		}
66		if rec.CommitID != c.ID || rec.PartID != "part1" || rec.Quantity != 4 {
67			t.Fatalf("bad submission fields: %+v", rec)
68		}
69		if !rec.Expiry.Equal(expiryOK) || !rec.Now.Equal(nowOK) {
70			t.Fatalf("bad times: expiry=%v now=%v", rec.Expiry, rec.Now)
71		}
72		// 资格依据快照。
73		if rec.Eligibility == nil {
74			t.Fatal("expected eligibility snapshot")
75		}
76		if !rec.Eligibility.Eligible || rec.Eligibility.PurchaseTime != t0 ||
77			rec.Eligibility.WarrantyDays != 30 || rec.Eligibility.WarrantyExpiry != t0.Add(30*day) ||
78			rec.Eligibility.Excluded || len(rec.Eligibility.Reasons) != 0 {
79			t.Fatalf("bad eligibility snapshot: %+v", rec.Eligibility)
80		}
81		// 库存依据：处理前实物 10、占用 0、可承诺 10。
82		if rec.StockBasis == nil {
83			t.Fatal("expected stock basis snapshot")
84		}
85		if rec.StockBasis.PhysicalRemaining != 10 || rec.StockBasis.ActiveOccupied != 0 ||
86			rec.StockBasis.Committable != 10 {
87			t.Fatalf("bad stock basis: %+v", rec.StockBasis)
88		}
89	}
90	
91	func TestHistoryIneligibleRecord(t *testing.T) {
92		s := historyStore(t)
93		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
94			t.Fatalf("submit: %v", err)
95		}
96		// 第 31 天：过保且除外，两项原因都保留。
97		if _, err := s.Reserve("c1", "rBad", "part1", 1, expiryOK, t0.Add(31*day)); !errors.Is(err, ErrIneligible) {
98			t.Fatalf("reserve: got %v", err)
99		}
100		h, _ := s.RequestHistory("rBad")
101		if len(h) != 1 {
102			t.Fatalf("history len = %d, want 1", len(h))
103		}
104		rec := h[0]
105		if rec.Success || rec.Error != HistoryErrorIneligible {
106			t.Fatalf("bad error category: success=%v error=%q", rec.Success, rec.Error)
107		}
108		if rec.Eligibility == nil {
109			t.Fatal("expected eligibility snapshot for ineligible record")
110		}
111		if rec.Eligibility.Eligible || !rec.Eligibility.Excluded {
112			t.Fatalf("expected ineligible+excluded: %+v", rec.Eligibility)
113		}
114		got := map[RejectionReason]bool{}
115		for _, r := range rec.Eligibility.Reasons {
116			got[r] = true
117		}
118		if !got[ReasonWarrantyExpired] || !got[ReasonFaultExcluded] {
119			t.Fatalf("reasons = %v, want both warranty_expired and fault_code_excluded", rec.Eligibility.Reasons)
120		}
121		// 库存依据仍保留（备件存在）。
122		if rec.StockBasis == nil || rec.StockBasis.Committable != 10 {
123			t.Fatalf("stock basis: %+v", rec.StockBasis)
124		}
125	}
126	
127	func TestHistoryInsufficientStockRecord(t *testing.T) {
128		s := historyStore(t)
129		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrInsufficientStock) {
130			t.Fatalf("reserve: got %v", err)
131		}
132		h, _ := s.RequestHistory("r1")
133		if len(h) != 1 {
134			t.Fatalf("history len = %d, want 1", len(h))
135		}
136		rec := h[0]
137		if rec.Success || rec.Error != HistoryErrorInsufficientStock {
138			t.Fatalf("bad error category: %q", rec.Error)
139		}
140		if rec.Eligibility == nil || !rec.Eligibility.Eligible {
141			t.Fatalf("expected eligible snapshot: %+v", rec.Eligibility)
142		}
143		if rec.StockBasis == nil {
144			t.Fatal("expected stock basis")
145		}
146		if rec.StockBasis.PhysicalRemaining != 10 || rec.StockBasis.ActiveOccupied != 0 ||
147			rec.StockBasis.Committable != 10 {
148			t.Fatalf("bad stock basis: %+v", rec.StockBasis)
149		}
150	}
151	
152	func TestHistoryMissingProductAndPart(t *testing.T) {
153		s := NewStore()
154		if err := s.RegisterProduct("p1", t0, 30, nil); err != nil {
155			t.Fatalf("register product: %v", err)
156		}
157		if err := s.RegisterPart("part1", 10); err != nil {
158			t.Fatalf("register part: %v", err)
159		}
160		// rNoProduct 关联尚未登记的产品；rNoPart 关联已登记产品但备件缺失。
161		if err := s.SubmitRequest("rNoProduct", "pMissing", "F"); err != nil {
162			t.Fatalf("submit: %v", err)
163		}
164		if err := s.SubmitRequest("rNoPart", "p1", "F"); err != nil {
165			t.Fatalf("submit: %v", err)
166		}
167	
168		// 产品缺失：已知请求的失败历史可查，资格与库存依据明确为空。
169		if _, err := s.Reserve("c1", "rNoProduct", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
170			t.Fatalf("reserve missing product: got %v", err)
171		}
172		h, err := s.RequestHistory("rNoProduct")
173		if err != nil {
174			t.Fatalf("history: %v", err)
175		}
176		if len(h) != 1 || h[0].Error != HistoryErrorProductNotFound {
177			t.Fatalf("missing product history: %+v", h)
178		}
179		if h[0].Eligibility != nil || h[0].StockBasis != nil {
180			t.Fatalf("expected nil eligibility & stock basis, got %+v", h[0])
181		}
182	
183		// 备件缺失：库存依据明确为空。
184		if _, err := s.Reserve("c2", "rNoPart", "partMissing", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
185			t.Fatalf("reserve missing part: got %v", err)
186		}
187		h2, err := s.RequestHistory("rNoPart")
188		if err != nil {
189			t.Fatalf("history: %v", err)
190		}
191		if len(h2) != 1 || h2[0].Error != HistoryErrorPartNotFound {
192			t.Fatalf("missing part history: %+v", h2)
193		}
194		if h2[0].Eligibility != nil || h2[0].StockBasis != nil {
195			t.Fatalf("expected nil eligibility & stock basis, got %+v", h2[0])
196		}
197	}
198	
199	func TestHistoryInvalidParamRecord(t *testing.T) {
200		s := historyStore(t)
201		// 数量非正：请求已知，记录参数无效。
202		if _, err := s.Reserve("c1", "r1", "part1", 0, expiryOK, nowOK); !errors.Is(err, ErrInvalidParam) {
203			t.Fatalf("zero quantity: got %v", err)
204		}
205		h, _ := s.RequestHistory("r1")
206		if len(h) != 1 || h[0].Error != HistoryErrorInvalidParam {
207			t.Fatalf("invalid param history: %+v", h)
208		}
209		if h[0].Eligibility != nil || h[0].StockBasis != nil {
210			t.Fatalf("expected nil basis for invalid param, got %+v", h[0])
211		}
212	
213		// 到期时刻未晚于当前时刻：同样记录。
214		if _, err := s.Reserve("c2", "r1", "part1", 1, nowOK, nowOK); !errors.Is(err, ErrInvalidParam) {
215			t.Fatalf("expiry equal now: got %v", err)
216		}
217		h, _ = s.RequestHistory("r1")
218		if len(h) != 2 || h[1].Error != HistoryErrorInvalidParam {
219			t.Fatalf("second invalid param history: %+v", h)
220		}
221	}
222	
223	func TestHistoryConflictRoutesToSubmissionRequest(t *testing.T) {
224		s := historyStore(t)
225		if err := s.SubmitRequest("r2", "p1", "FAULTY"); err != nil {
226			t.Fatalf("submit r2: %v", err)
227		}
228		// c1 挂在 r1 下。
229		if _, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK); err != nil {
230			t.Fatalf("reserve: %v", err)
231		}
232		// 同编号改内容（换请求）→ 冲突，失败记录挂到本次提交指定的 r2，不挂 r1。
233		if _, err := s.Reserve("c1", "r2", "part1", 5, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
234			t.Fatalf("conflict: got %v", err)
235		}
236		h1, _ := s.RequestHistory("r1")
237		if len(h1) != 1 || !h1[0].Success {
238			t.Fatalf("r1 history should only have the success, got %+v", h1)
239		}
240		h2, _ := s.RequestHistory("r2")
241		if len(h2) != 1 || h2[0].Success || h2[0].Error != HistoryErrorConflict {
242			t.Fatalf("r2 history should have the conflict failure, got %+v", h2)
243		}
244		if h2[0].Eligibility != nil || h2[0].StockBasis != nil {
245			t.Fatalf("conflict record should have nil basis, got %+v", h2[0])
246		}
247	}
248	
249	func TestHistoryIdempotentRetryAppendsNothing(t *testing.T) {
250		s := historyStore(t)
251		if _, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK); err != nil {
252			t.Fatalf("reserve: %v", err)
253		}
254		// 同编号同内容重试：不追加历史。
255		if _, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK); err != nil {
256			t.Fatalf("retry: %v", err)
257		}
258		h, _ := s.RequestHistory("r1")
259		if len(h) != 1 {
260			t.Fatalf("idempotent retry appended history: len=%d", len(h))
261		}
262	}
263	
264	func TestHistoryFailedSubmissionReusableAndNotOverwritten(t *testing.T) {
265		s := historyStore(t)
266		// 库存不足失败：不占用承诺编号。
267		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrInsufficientStock) {
268			t.Fatalf("over-stock: got %v", err)
269		}
270		// 条件满足后用同编号重新提交成功。
271		if _, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK); err != nil {
272			t.Fatalf("reserve after restock: %v", err)
273		}
274		h, _ := s.RequestHistory("r1")
275		if len(h) != 2 {
