277		}
278		if h[0].Success || h[0].Error != HistoryErrorInsufficientStock {
279			t.Fatalf("first record should be failure: %+v", h[0])
280		}
281		if !h[1].Success || h[1].Error != "" {
282			t.Fatalf("second record should be success: %+v", h[1])
283		}
284		// 承诺编号只被占用一次。
285		st, _ := s.PartStatus("part1", nowOK)
286		if st.ActiveOccupied != 4 {
287			t.Fatalf("active occupied = %d, want 4", st.ActiveOccupied)
288		}
289	}
290	
291	func TestHistoryOrderingAndSeq(t *testing.T) {
292		s := historyStore(t)
293		if err := s.SubmitRequest("r2", "p1", "FAULTY"); err != nil {
294			t.Fatalf("submit r2: %v", err)
295		}
