304		if _, err := s.Reserve("c10", "r2", "part1", 1, expiryOK, nowOK); err != nil {
305			t.Fatalf("reserve r2: %v", err)
306		}
307		h1, _ := s.RequestHistory("r1")
308		if len(h1) != 4 {
309			t.Fatalf("r1 history len = %d, want 4", len(h1))
310		}
311		for i, rec := range h1 {
312			if rec.Seq != i+1 {
