342	func TestHistorySnapshotUnchangedAfterUseCancelExpire(t *testing.T) {
343		s := historyStore(t)
344		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
345			t.Fatalf("reserve: %v", err)
346		}
347		h, _ := s.RequestHistory("r1")
348		before := h[0]
349		// 使用、取消、到期都不改变历史中的依据与数量。
350		if _, err := s.Use("u1", "c1", 3, nowOK); err != nil {
351			t.Fatalf("use: %v", err)
352		}
353		if _, err := s.Cancel("c1", nowOK); err != nil {
354			t.Fatalf("cancel: %v", err)
355		}
356		h2, _ := s.RequestHistory("r1")
357		after := h2[0]
358		if after.Quantity != before.Quantity || after.StockBasis.PhysicalRemaining != before.StockBasis.PhysicalRemaining ||
359			after.StockBasis.ActiveOccupied != before.StockBasis.ActiveOccupied ||
360			after.StockBasis.Committable != before.StockBasis.Committable {
361			t.Fatalf("history changed after use/cancel: before=%+v after=%+v", before, after)
